PROGRAM AlarmLatch
VAR_INPUT Fault AT %I0.0 : BOOL; Ack AT %I0.1 : BOOL; END_VAR
VAR_OUTPUT SetFirst AT %Q0.0 : BOOL; ResetFirst AT %Q0.1 : BOOL; END_VAR
VAR SetLatch : SR; ResetLatch : RS; END_VAR
IF Fault THEN SetFirst := TRUE; ELSIF Ack THEN SetFirst := FALSE; END_IF;
IF Ack THEN ResetFirst := FALSE; ELSIF Fault THEN ResetFirst := TRUE; END_IF;
SetFirst := SetFirst AND (Fault OR NOT Ack);
END_PROGRAM
